            owl:someValuesFrom ns1:TobascoPepperSauce ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:TomatoTopping ],
        [ a owl:Restriction ;
            owl:allValuesFrom [ a owl:Class ;
                    owl:unionOf ( ns1:MozzarellaTopping ns1:OnionTopping ns1:PeperonataTopping ns1:PrawnsTopping ns1:TobascoPepperSauce ns1:TomatoTopping ) ] ;
            owl:onProperty ns1:hasTopping ],
        ns1:NamedPizza ;
    skos:altLabel "Cajun"@en,
        "Cajun Pizza"@en ;
    skos:prefLabel "Cajun"@en .

ns1:Capricciosa a owl:Class ;
    rdfs:label "Capricciosa"@en,
        "Capricciosa"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:AnchoviesTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:CaperTopping ],
        [ a owl:Restriction ;
