        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:TomatoTopping ],
        [ a owl:Restriction ;
            owl:allValuesFrom [ a owl:Class ;
                    owl:unionOf ( ns1:AnchoviesTopping ns1:CaperTopping ns1:HamTopping ns1:MozzarellaTopping ns1:OliveTopping ns1:PeperonataTopping ns1:TomatoTopping ) ] ;
            owl:onProperty ns1:hasTopping ],
        ns1:NamedPizza ;
    skos:altLabel "Capricciosa"@en,
        "Capricciosa Pizza"@en ;
    skos:prefLabel "Capricciosa"@en .

ns1:Caprina a owl:Class ;
    rdfs:label "Caprina"@en,
        "Caprina"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:GoatsCheeseTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:MozzarellaTopping ],
        [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:SundriedTomatoTopping ],
        [ a owl:Restriction ;
