        [ a owl:Restriction ;
            owl:allValuesFrom [ a owl:Class ;
                    owl:unionOf ( ns1:GoatsCheeseTopping ns1:MozzarellaTopping ns1:SundriedTomatoTopping ns1:TomatoTopping ) ] ;
            owl:onProperty ns1:hasTopping ],
        ns1:NamedPizza ;
    skos:altLabel "Caprina"@en,
        "Caprina Pizza"@en ;
    skos:prefLabel "Caprina"@en .

ns1:DomainConcept a owl:Class ;
    rdfs:label "DomainThing"@en ;
    owl:disjointWith ns1:ValuePartition ;
    skos:prefLabel "Domain Thing"@en .

ns1:Fiorentina a owl:Class ;
    rdfs:label "Fiorentina"@en,
