ns1:FruttiDiMare a owl:Class ;
    rdfs:label "FruttiDiMare"@en,
        "FrutosDoMar"@pt ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty ns1:hasTopping ;
            owl:someValuesFrom ns1:GarlicTopping ],
        [ a owl:Restriction ;
