<http://www.co-ode.org/ontologies/pizza/PolloAdAstra_91> a owl:NamedIndividual ;
    ns1:hasTopping <http://www.co-ode.org/ontologies/pizza/ChickenTopping_dynamic_1> .

<http://www.co-ode.org/ontologies/pizza/PolloAdAstra_95> a owl:NamedIndividual ;
