@prefix ns1: <https://kracr.iiitd.edu.in/OWL2Bench#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/extracted/1hop/Person_58> a owl:Ontology ;
    rdfs:label "OWL2Bench Individual Subgraph (1-hop)"@en ;
    rdfs:comment "A Benchmark for OWL 2 Ontologies. Individual-centered 1-hop extraction." ;
    owl:versionInfo "OWL2Bench, ver 2020" .

owl:Thing a owl:Class .

ns1:Chair a owl:Class ;
    rdfs:subClassOf ns1:FullProfessor ;
    owl:equivalentClass [ a owl:Restriction ;
            owl:onProperty ns1:isHeadOf ;
            owl:someValuesFrom ns1:Department ] .

ns1:CoEdCollege a owl:Class ;
    rdfs:subClassOf ns1:College .

ns1:Dean a owl:Class ;
    rdfs:subClassOf ns1:FullProfessor ;
    owl:equivalentClass [ a owl:Restriction ;
            owl:onProperty ns1:isHeadOf ;
            owl:someValuesFrom ns1:College ] .

ns1:Director a owl:Class ;
    rdfs:subClassOf ns1:FullProfessor ;
    owl:equivalentClass [ a owl:Restriction ;
            owl:onProperty ns1:isHeadOf ;
            owl:someValuesFrom ns1:Program ] .

ns1:Institute a owl:Class ;
    rdfs:subClassOf ns1:Organization .

ns1:LeisureStudent a owl:Class ;
    rdfs:subClassOf ns1:Student ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Student [ a owl:Restriction ;
                        owl:maxQualifiedCardinality "1"^^xsd:nonNegativeInteger ;
                        owl:onClass ns1:Course ;
                        owl:onProperty ns1:takesCourse ] ) ] .

ns1:NonScience a owl:Class ;
    rdfs:subClassOf ns1:CollegeDiscipline ;
    owl:equivalentClass [ a owl:Class ;
            owl:complementOf ns1:Science ] .

ns1:PGStudent a owl:Class ;
    rdfs:subClassOf ns1:Student ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Student [ a owl:Restriction ;
                        owl:onClass ns1:PGProgram ;
                        owl:onProperty ns1:enrollFor ;
                        owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ] ) ] .

ns1:PeopleWithHobby a owl:Class ;
    rdfs:subClassOf ns1:Person ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Person [ a owl:Restriction ;
                        owl:onProperty ns1:likes ;
                        owl:someValuesFrom ns1:Interest ] ) ] .

ns1:PeopleWithManyHobbies a owl:Class ;
    rdfs:subClassOf ns1:Person ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Person [ a owl:Restriction ;
                        owl:minQualifiedCardinality "3"^^xsd:nonNegativeInteger ;
                        owl:onClass ns1:Interest ;
                        owl:onProperty ns1:likes ] ) ] .

ns1:Person_58 a owl:NamedIndividual,
        ns1:Person ;
    ns1:hasDoctoralDegreeFrom ns1:University_13 ;
    ns1:takesCourse ns1:Course_14 ;
    ns1:teachesCourse ns1:Course_19 .

ns1:PhDStudent a owl:Class ;
    rdfs:subClassOf ns1:Student ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Student [ a owl:Restriction ;
                        owl:onClass ns1:PhDProgram ;
                        owl:onProperty ns1:enrollFor ;
                        owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ] ) ] .

ns1:Reading a owl:Class ;
    rdfs:subClassOf ns1:Interest .

ns1:SelfAwarePerson a owl:Class ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Person [ a owl:Restriction ;
                        owl:hasSelf true ;
                        owl:onProperty ns1:knows ] ) ] .

ns1:T20CricketFan a owl:Class ;
    rdfs:subClassOf ns1:Person .

ns1:Travelling a owl:Class ;
    rdfs:subClassOf ns1:Interest .

ns1:UGStudent a owl:Class ;
    rdfs:subClassOf ns1:Student ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:Student [ a owl:Restriction ;
                        owl:onClass ns1:UGProgram ;
                        owl:onProperty ns1:enrollFor ;
                        owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ] ) ] .

ns1:WomenCollege a owl:Class ;
    rdfs:subClassOf ns1:College ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ns1:College [ a owl:Restriction ;
                        owl:allValuesFrom ns1:Woman ;
                        owl:onProperty ns1:hasStudent ] ) ] .

ns1:advises a owl:ObjectProperty ;
    owl:equivalentProperty ns1:isAdvisorOf .

ns1:dislikes a owl:ObjectProperty ;
    rdfs:domain ns1:Person ;
    rdfs:subPropertyOf owl:topObjectProperty ;
    owl:propertyDisjointWith ns1:likes .

ns1:hasAdvisor a owl:ObjectProperty ;
    owl:equivalentProperty ns1:isAdvisedBy .

ns1:hasAge a owl:DatatypeProperty,
        owl:FunctionalProperty ;
    rdfs:domain ns1:Person .

ns1:hasAlumnus a owl:ObjectProperty ;
    rdfs:domain ns1:University ;
    rdfs:range ns1:Person ;
    owl:inverseOf ns1:hasDegreeFrom .

ns1:hasAssistantProfessor a owl:ObjectProperty ;
    rdfs:domain ns1:Department ;
    rdfs:range ns1:AssistantProfessor ;
    rdfs:subPropertyOf ns1:hasProfessor ;
